  'thermal-analysis':{conditions:[['Temperature range','°C'],['Heating rate','°C/min'],['Atmosphere',''],['Sample mass','mg']],materials:[['Sample','measured specimen'],['Pan / crucible','sample container'],['Purge gas','test atmosphere']]},
  'cell-culture':{conditions:[['Cell density','cells/mL'],['Medium volume','mL'],['Incubation temperature','°C'],['Treatment duration','h']],materials:[['Cell line / sample','biological material'],['Culture medium','growth medium'],['Treatment reagent','experimental input'],['Control','comparison group']]},
  'pcr-qpcr':{conditions:[['Template amount','ng'],['Primer concentration','µM'],['Cycle count',''],['Annealing temperature','°C']],materials:[['Template nucleic acid','target'],['Forward / reverse primers','amplification'],['Master mix','reaction mix'],['Positive / negative control','quality control']]},
  sequencing:{conditions:[['Input nucleic acid amount','ng'],['Library cycles',''],['Read length','bp'],['Target depth','']],materials:[['DNA / RNA sample','input'],['Library preparation kit','library reagents'],['Index adapters','sample barcoding']]},
  'flow-cytometry':{conditions:[['Cell concentration','cells/mL'],['Staining duration','min'],['Detector / laser setup',''],['Events collected','']],materials:[['Cell suspension','sample'],['Antibody / stain panel','labeling'],['Compensation controls','fluorescence controls']]},
  elisa:{conditions:[['Sample dilution',''],['Incubation duration','min'],['Wash count',''],['Read wavelength','nm']],materials:[['Sample','analyte'],['Capture / detection antibody','recognition'],['Standards','calibration'],['Substrate reagent','signal development']]},
  'western-blot':{conditions:[['Protein load','µg'],['Gel percentage','%'],['Transfer voltage','V'],['Antibody dilution','']],materials:[['Protein lysate','sample'],['Gel / membrane','separation and transfer'],['Primary / secondary antibodies','detection'],['Ladder','size reference']]},
